function initializeSlider() {
    if (window.innerWidth < 765) {
        isMobile = true;
    } else {
        isMobile = false;
        // Reset für Desktop, falls man das Fenster vergrößert
        const cardContainer = document.querySelector('.service-slider');
        if (cardContainer) cardContainer.style.transform = 'translateX(0px)';
    }
}

document.addEventListener('DOMContentLoaded', () => {
    setTimeout(() => {
        initializeSlider();
        selectCard('gold_membership');
    }, 200);
})

function moveSlide(index) {
    let membershipCards = document.querySelectorAll('.membershipcard');
    membershipCards.forEach((card) => {
        card.classList.remove('selected');
    });
    // HIER IST DIE ÄNDERUNG: Die Klasse geht jetzt an den Container, nicht an das Bild
    membershipCards[index].classList.add('selected');

    let membershipCardContainers = document.querySelectorAll('.membership-card-container');
    membershipCardContainers.forEach((container) => {
        container.classList.remove('selected');
    });
    membershipCardContainers[index].classList.add('selected');

    let membershipCardLinks = document.querySelectorAll('.membership-card-select-link');
    membershipCardLinks.forEach((link) => {
        link.classList.remove('active');
    });
    membershipCardLinks[index].classList.add('active');

    if (isMobile) {
        const wrapper = document.querySelector('.service-slider-wrapper');
        const cardContainer = document.querySelector('.service-slider');
        const cardItems = document.querySelectorAll('.membership-card-container');

        // Breite der Karte und der Abstand (Gap: 32px laut CSS)
        const cardWidth = cardItems[0].offsetWidth;
        const gap = 30; // Falls dein CSS-Gap 32px ist, solltest du das hier evtl. auf 32 anpassen!
        const step = cardWidth + gap;

        // Verfügbare Breite berechnen (clientWidth minus 60px Padding des Wrappers)
        const contentBoxWidth = wrapper.clientWidth - 60;

        // Berechnen, wie weit verschoben werden muss, um die Karte im Container zu zentrieren
        const centerOffset = (contentBoxWidth / 2) - (cardWidth / 2);

        // Verschiebung: Zentrierungspunkt minus die Position der aktuellen Karte
        let translation = centerOffset - (index * step);

        cardContainer.style.transform = `translateX(${translation}px)`;
    }
}

function moveSlideDesktop(index) {
    let membershipCards = document.querySelectorAll('.membershipcard');
    membershipCards.forEach((card) => {
        card.classList.remove('selected');
    });
    membershipCards[index].classList.add('selected');

    let membershipCardContainers = document.querySelectorAll('.membership-card-container');
    membershipCardContainers.forEach((container) => {
        container.classList.remove('selected')
    })
    membershipCardContainers[index].classList.add('selected');

    membershipCardContainers.forEach((container) => {
        container.style.zIndex = "";
    })
    membershipCards[index].classList.add('selected');
    membershipCardContainers[index].style.zIndex = "10";

    let membershipCardLinks = document.querySelectorAll('.membership-card-select-link');
    membershipCardLinks.forEach((link) => {
        link.classList.remove('active')
    })
    membershipCardLinks[index].classList.add('active');

    /* shuffleCards(); */
}

function shuffleCards() {
    const cards = document.querySelectorAll(".membership-card-container");
    const slider = document.querySelector(".service-slider");
    // 1. Karten in die Mitte stapeln
    gsap.to(cards, {
        duration: 0.5,
        left: 0,
        scale: 0.8,
        stagger: 0.1,
        ease: "power2.inOut"
    });

    // 2. Neue Reihenfolge bestimmen (z. B. zufällig)
    setTimeout(() => {
        const shuffled = Array.from(cards).sort(() => Math.random() - 0.5);
        shuffled.forEach((card, index) => slider.appendChild(card));

        // 3. Karten wieder aufklappen
        gsap.to(cards, {
            duration: 0.5,
            left: (i) => i * 200 + 30, // Abstand zwischen den Karten anpassen
            scale: (i) => 1 - i * 0.1,
            stagger: 0.1,
            ease: "power2.out"
        });
    }, 600);
}

