function updateChipSwitch(cardId) {
    const switchRow = document.querySelector('.membership-card-select-row');
    if (!switchRow) return;

    const indicator = switchRow.querySelector('.membership-card-switch-indicator');
    const activeLink = switchRow.querySelector(`.membership-card-select-link.${cardId}`);
    if (!indicator || !activeLink) return;

    switchRow.classList.remove(...cards);
    switchRow.classList.add(cardId);

    indicator.style.width = `${activeLink.offsetWidth}px`;
    indicator.style.transform = `translateX(${activeLink.offsetLeft}px)`;
}

function updateAntriebSwitch() {
    const switchRow = document.querySelector('.antrieb-select-row');
    if (!switchRow) return;

    const indicator = switchRow.querySelector('.antrieb-switch-indicator');
    const activeLink = switchRow.querySelector(`.antrieb-select-link.${antrieb}`);
    if (!indicator || !activeLink) return;

    switchRow.classList.remove(...antriebe);
    switchRow.classList.add(antrieb);
    switchRow.querySelectorAll('.antrieb-select-link').forEach(link => {
        link.classList.toggle('active', link === activeLink);
    });

    indicator.style.width = `${activeLink.offsetWidth}px`;
    indicator.style.transform = `translateX(${activeLink.offsetLeft}px)`;
}

