// Aktionsspalte nur zeigen, wenn die Aktion aktiviert ist und heute im Aktionszeitraum liegt
function aktionLaeuftHeute() {
    if (!gfTabelleAktion.aktiv) return false;
    const heute = new Date();
    if (gfTabelleAktion.von && heute < new Date(gfTabelleAktion.von + 'T00:00:00')) return false;
    if (gfTabelleAktion.bis && heute > new Date(gfTabelleAktion.bis + 'T23:59:59.999')) return false;
    return true;
}

function escapeHtml(text) {
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}

function roundPrice(value) {
    return Math.round(value * 100) / 100;
}

function hatKraftstoffzuschlag() {
    return antrieb === 'verbrenner' && !!gfTabelleKraftstoffzuschlag.value;
}

// Kilometerpreis inkl. Tarifrabatt und Kraftstoffzuschlag (der Zuschlag selbst wird nicht rabattiert)
function getKmPrice(basePrice, discount) {
    let price = basePrice * (1 - discount);
    if (hatKraftstoffzuschlag()) {
        price += gfTabelleKraftstoffzuschlag.isPercent ?
            basePrice * gfTabelleKraftstoffzuschlag.value / 100 :
            gfTabelleKraftstoffzuschlag.value;
    }
    return roundPrice(Math.max(0, price));
}

function formatTablePrice(value, td) {
    if (td.dataset.type === 'km') {
        return `+ ${value.toFixed(2)} € / km`;
    }
    return `${value.toFixed(2)} €${td.dataset.hourly === 'true' ? ' / h' : ''}`;
}

function formatKraftstoffzuschlag() {
    return gfTabelleKraftstoffzuschlag.isPercent ?
        `${gfTabelleKraftstoffzuschlag.value.toLocaleString('de-DE')} %` :
        `${gfTabelleKraftstoffzuschlag.value.toFixed(2)} € / km`;
}

function createPriceCell(basePrice, type, isHourly, columnIndex) {
    const td = document.createElement('td');
    td.classList.add('gf-table-price');
    if (type === 'km') td.classList.add('gf-table-milage-price');

    if (isNaN(basePrice)) {
        td.textContent = 'N/A';
        return td;
    }

    td.dataset.base = basePrice;
    td.dataset.type = type;
    td.dataset.hourly = isHourly;
    td.dataset.column = columnIndex;
    td.innerHTML = '<div class="gf-price-cell"><span class="gf-old-price"></span><span class="gf-new-price"></span></div>';

    // Startwert = Preis ohne Tarifrabatt, damit der erste Tarifwechsel sichtbar animiert
    td._gfPrice = {
        value: type === 'km' ? getKmPrice(basePrice, 0) : basePrice
    };
    td.querySelector('.gf-new-price').textContent = formatTablePrice(td._gfPrice.value, td);
    return td;
}

// Tabelle wird einmalig aufgebaut, beim Tarifwechsel werden nur die Preise animiert
function buildTable(selectedData) {
    const tableContainer = document.querySelector('.price-table-wrapper');
    tableContainer.innerHTML = '';

    const timeColumns = selectedData.tableData.filter(row => !row.isPromo || aktionLaeuftHeute());

    const table = document.createElement('table');
    table.classList.add('price-table');

    const thead = document.createElement('thead');
    const tbody = document.createElement('tbody');

    // Pre-header Row
    const preHeaderRow = document.createElement('tr');

    const preHeaderTdEmpty = document.createElement('td');
    preHeaderTdEmpty.classList.add('fixed-column', 'gf-table-pre-header');
    preHeaderRow.appendChild(preHeaderTdEmpty);

    const preHeaderTdTime = document.createElement('td');
    preHeaderTdTime.setAttribute('colspan', timeColumns.length);
    preHeaderTdTime.classList.add('gf-combined-price-preview');
    preHeaderTdTime.innerHTML =
        '<span class="gf-combined-price-highlight">Zeitpreis<span class="gf-discount-hint gf-time-discount-hint" style="display: none"></span></span>';
    preHeaderRow.appendChild(preHeaderTdTime);

    const preHeaderTdKm = document.createElement('td');
    preHeaderTdKm.setAttribute('colspan', selectedData.milage_pricing.length);
    preHeaderTdKm.classList.add('gf-combined-price-preview');
    preHeaderTdKm.innerHTML =
        '<span class="gf-combined-price-highlight">Kilometerpreis<span class="gf-discount-hint gf-km-discount-hint" style="display: none"></span></span>';
    preHeaderRow.appendChild(preHeaderTdKm);

    thead.appendChild(preHeaderRow);

    // --- HEADER ROW GENERIERUNG ---
    const headerRow = document.createElement('tr');
    headerRow.classList.add('gf-table-head-row');

    const headerTh = document.createElement('th');
    headerTh.classList.add('fixed-column');
    headerTh.textContent = 'Klassen';
    headerRow.appendChild(headerTh);

    timeColumns.forEach(row => {
        const th = document.createElement('th');
        th.classList.add('column_header');

        if (row.isNew) {
            const notice = document.createElement('span');
            notice.classList.add('new');
            notice.textContent = "Jetzt neu!";
            th.appendChild(notice)
        } else if (row.isPromo) {
            th.classList.add('promo-header');
            let actionSpan = document.createElement('span');
            actionSpan.classList.add('promo-header-span');
            actionSpan.textContent = row.title;
            th.appendChild(actionSpan);
        } else {
            th.textContent = row.title;
        }
        headerRow.appendChild(th);
    });

    selectedData.milage_pricing.forEach(row => {
        const th = document.createElement('th');
        th.classList.add('column_header');
        th.innerHTML = `${row.title}<span class="gf-km-suffix"></span>`;
        headerRow.appendChild(th);
    });

    thead.appendChild(headerRow);

    // --- DATA ROWS GENERIERUNG ---
    tableClasses.forEach((classItem, rowIndex) => {
        const row = document.createElement('tr');

        const classTd = document.createElement('td');
        classTd.classList.add('fixed-column');
        classTd.innerHTML = `<span class="priceMarker">${classItem.name}</span>`;
        row.appendChild(classTd);

        timeColumns.forEach((data, columnIndex) => {
            if (data.isPromo) {
                // Promo-Zelle nur in der ersten Zeile rendern, sie überspannt alle Klassen-Zeilen
                if (rowIndex === 0) {
                    const td = document.createElement('td');
                    td.classList.add('gf-table-price', 'gf-table-promo-price');
                    td.rowSpan = tableClasses.length;
                    td.style.backgroundColor = data.promoBgColor || "#82ba26";
                    td.style.border = "none";

                    let html = `<div class="gf-promo-content">`;
                    if (data.promoImage) {
                        html += `<img decoding="async" src="${data.promoImage}" alt="Aktion" />`;
                    }
                    if (gfTabelleAktion.text) {
                        html += `<span class="gf-promo-text">${escapeHtml(gfTabelleAktion.text)}</span>`;
                    }
                    if (gfTabelleAktion.untertext) {
                        html += `<span class="gf-promo-subtext">${escapeHtml(gfTabelleAktion.untertext)}</span>`;
                    }
                    html += `</div>`;

                    td.innerHTML = html;
                    row.appendChild(td);
                }
            } else {
                const isHourlyPrice = data.title === '0-7 Uhr' || data.title === '7-24 Uhr';
                row.appendChild(createPriceCell(parseFloat(data.classData[classItem.name]), 'time', isHourlyPrice, columnIndex));
            }
        });

        selectedData.milage_pricing.forEach((data, kmIndex) => {
            row.appendChild(createPriceCell(parseFloat(data.classData[classItem.name]), 'km', false, timeColumns.length + kmIndex));
        });

        tbody.appendChild(row);
    });

    table.appendChild(thead);
    table.appendChild(tbody);
    tableContainer.appendChild(table);
}

function updateDiscountHint(hint, discount, service) {
    if (!hint) return;
    if (!discount) {
        hint.style.display = 'none';
        return;
    }
    hint.classList.remove('gf-discount-hint-gold', 'gf-discount-hint-black');
    hint.classList.add(service === 'gold_membership' ? 'gf-discount-hint-gold' : 'gf-discount-hint-black');
    hint.textContent = `inkl. ${Math.round(discount * 100)}% Rabatt`;
    const wasHidden = hint.style.display === 'none';
    hint.style.display = '';
    if (wasHidden && typeof gsap !== 'undefined') {
        gsap.fromTo(hint, {
            scale: 0.6,
            opacity: 0
        }, {
            scale: 1,
            opacity: 1,
            duration: 0.35,
            ease: 'back.out(2)'
        });
    }
}

function updateLegend(rabatt) {
    const legend = document.querySelector('.gf-price-table-legend');
    if (!legend) return;

    let html = '';
    if (rabatt.time || rabatt.km) {
        const parts = [];
        if (rabatt.time) parts.push('Zeitpreis');
        if (rabatt.km) parts.push('Kilometerpreis');
        const percent = Math.round(Math.max(rabatt.time, rabatt.km) * 100);
        html += `<p>Im Tarif ${rabatt.label} ist der ${percent}% Rabatt auf ${parts.join(' und ')} bereits in den Preisen enthalten. <span class="gf-old-price-sample">Durchgestrichen</span>: Preis ohne Rabatt.</p>`;
    }
    if (hatKraftstoffzuschlag()) {
        html += `<p>* Kilometerpreise inkl. Kraftstoffzuschlag von ${formatKraftstoffzuschlag()}.</p>`;
    }
    legend.innerHTML = html;
}

function updateTablePrices(service, animate = true) {
    const rabatt = tarifRabatte[service] || tarifRabatte.green_membership;
    const tableContainer = document.querySelector('.price-table-wrapper');
    const useGsap = animate && typeof gsap !== 'undefined';

    tableContainer.querySelectorAll('td[data-base]').forEach(td => {
        const basePrice = parseFloat(td.dataset.base);
        const isKm = td.dataset.type === 'km';
        const originalPrice = isKm ? getKmPrice(basePrice, 0) : basePrice;
        const targetPrice = isKm ? getKmPrice(basePrice, rabatt.km) : roundPrice(basePrice * (1 - rabatt.time));
        const isReduced = targetPrice < originalPrice;

        const newPriceEl = td.querySelector('.gf-new-price');
        const oldPriceEl = td.querySelector('.gf-old-price');
        const state = td._gfPrice;
        const renderPrice = () => {
            newPriceEl.textContent = formatTablePrice(state.value, td);
        };

        td.classList.toggle('gf-price-reduced', isReduced);
        oldPriceEl.setAttribute('aria-hidden', isReduced ? 'false' : 'true');
        if (isReduced) {
            oldPriceEl.textContent = formatTablePrice(originalPrice, td);
        }

        if (useGsap) {
            gsap.killTweensOf([state, oldPriceEl]);
            // Spaltenweise leicht versetzt, damit die Änderung pro Spalte sichtbar "durchläuft"
            gsap.to(state, {
                value: targetPrice,
                duration: 0.7,
                delay: Number(td.dataset.column) * 0.05,
                ease: 'power2.out',
                onUpdate: renderPrice,
                onComplete: () => {
                    state.value = targetPrice;
                    renderPrice();
                }
            });
            gsap.to(oldPriceEl, {
                height: isReduced ? 'auto' : 0,
                opacity: isReduced ? 0.65 : 0,
                duration: 0.35,
                ease: 'power1.out'
            });
        } else {
            if (typeof gsap !== 'undefined') gsap.killTweensOf([state, oldPriceEl]);
            state.value = targetPrice;
            renderPrice();
            oldPriceEl.style.height = isReduced ? 'auto' : '0px';
            oldPriceEl.style.opacity = isReduced ? '0.65' : '0';
        }
    });

    updateDiscountHint(tableContainer.querySelector('.gf-time-discount-hint'), rabatt.time, service);
    updateDiscountHint(tableContainer.querySelector('.gf-km-discount-hint'), rabatt.km, service);
    updateAntriebSwitch();
    tableContainer.querySelectorAll('.gf-km-suffix').forEach(suffix => {
        suffix.textContent = hatKraftstoffzuschlag() ? '*' : '';
    });
    updateLegend(rabatt);
}

