// Aktion gilt, wenn sie heute läuft und die Fahrt spätestens am letzten Aktionstag beginnt
function aktionGiltFuer(fahrtStart) {
    if (!gfRechnerAktion.aktiv) return false;
    const heute = new Date();
    const von = gfRechnerAktion.von ? new Date(gfRechnerAktion.von + 'T00:00:00') : null;
    const bisEnde = gfRechnerAktion.bis ? new Date(gfRechnerAktion.bis + 'T23:59:59.999') : null;
    if (von && heute < von) return false;
    if (bisEnde && (heute > bisEnde || fahrtStart > bisEnde)) return false;
    return true;
}

function berechneMietpreis(selectedMembersip, fahrzeugGroesse, startDatum, endDatum, kilometer, includeCredit) {
    // Einheitliche Basis-Tarife für alle Karten
    const basisTarif = {
        'XS': {
            'nacht': 0.00,
            'tag': 1.80
        },
        'S': {
            'nacht': 0.00,
            'tag': 2.30
        },
        'M': {
            'nacht': 0.00,
            'tag': 2.90
        },
        'L': {
            'nacht': 0.00,
            'tag': 3.60
        },
        'XL': {
            'nacht': 1.00,
            'tag': 4.60
        },
        'XXL': {
            'nacht': 1.00,
            'tag': 5.00
        },
        'tagesTarife': {
            'XS': 29,
            'S': 38,
            'M': 48,
            'L': 57,
            'XL': 74,
            'XXL': 80
        },
        'wochenTarife': {
            'XS': 155,
            'S': 195,
            'M': 245,
            'L': 295,
            'XL': 375,
            'XXL': 405
        },
        'kilometerTarife': {
            'unter100': {
                'XS': 0.30,
                'S': 0.32,
                'M': 0.36,
                'L': 0.36,
                'XL': 0.41,
                'XXL': 0.43
            },
            'ueber100': {
                'XS': 0.27,
                'S': 0.29,
                'M': 0.33,
                'L': 0.33,
                'XL': 0.38,
                'XXL': 0.40
            }
        }
    };

    const tarife = {
        'green_membership': basisTarif,
        'gold_membership': basisTarif,
        'black_membership': basisTarif
    };
    // Hilfsfunktionen
    function istNachtstunde(stunde) {
        return stunde >= 0 && stunde < 7;
    }

    function berechneStundenPreis(stunden, tarif) {
        let preis = 0;
        stunden.forEach(stunde => {
            preis += istNachtstunde(stunde) ? tarif.nacht : tarif.tag;
        });
        return preis;
    }

    function berechneKilometerPreis(kilometer, tarif) {
        return kilometer * tarif;
    }

    let gesamtPreis = 0;
    let promoAktiv = false;
    const start = new Date(startDatum);
    const ende = new Date(endDatum);

    // Mindestens 1 Stunde berechnen
    let differenzMs = ende - start;
    if (differenzMs < 60 * 60 * 1000) {
        differenzMs = 60 * 60 * 1000;
    }

    // Aktion 4-fuer-3: Zeitpreis bei 96-120h, 1 Tag geschenkt
    if (aktionGiltFuer(start)) {
        const dauerStunden = differenzMs / (60 * 60 * 1000);
        if (dauerStunden >= 96 && dauerStunden <= 120) {
            differenzMs -= 24 * 60 * 60 * 1000;
            promoAktiv = true;
        }
    }

    // Aufteilung in reale Wochen, Tage und Stunden
    const anzahlWochen = Math.floor(differenzMs / (7 * 24 * 60 * 60 * 1000));
    let verbleibendeMs = differenzMs % (7 * 24 * 60 * 60 * 1000);

    const anzahlTage = Math.floor(verbleibendeMs / (24 * 60 * 60 * 1000));
    verbleibendeMs = verbleibendeMs % (24 * 60 * 60 * 1000);

    const anzahlStunden = Math.ceil(verbleibendeMs / (60 * 60 * 1000));

    // Tarif-Referenzen für einfacheres Lesen
    const tarif = tarife[selectedMembersip];
    const fzTarif = tarif[fahrzeugGroesse];
    const tagesPreis = tarif.tagesTarife[fahrzeugGroesse];
    const dreiTagesPreis = tagesPreis * 3;
    const wochenPreis = tarif.wochenTarife[fahrzeugGroesse];

    // 1. Stundenkosten berechnen & deckeln (Eine Stundensammlung darf nie teurer als 1 Tag sein)
    let stundenKosten = 0;
    if (anzahlStunden > 0) {
        const stundenArray = [];
        const startZeitRest = new Date(start.getTime() + anzahlWochen * 7 * 24 * 60 * 60 * 1000 + anzahlTage * 24 * 60 * 60 * 1000);

        for (let i = 0; i < anzahlStunden; i++) {
            const currentHour = new Date(startZeitRest.getTime() + i * 60 * 60 * 1000);
            stundenArray.push(currentHour.getHours());
        }
        stundenKosten = berechneStundenPreis(stundenArray, fzTarif);

        if (stundenKosten > tagesPreis) {
            stundenKosten = tagesPreis; // Deckelung auf Tagespreis
        }
    }

    // 2. Best-Price Algorithmus (Paket-Berechnung)
    function getBestTimePrice(w, d, h_cost) {
        // Tage in Wochen umwandeln, falls durch Aufrunden >= 7
        w += Math.floor(d / 7);
        d = d % 7;

        // Verbleibende Tage optimal in 3-Tages-Blöcke und Einzeltage packen
        let d3 = Math.floor(d / 3);
        let d1 = d % 3;

        return (w * wochenPreis) + (d3 * dreiTagesPreis) + (d1 * tagesPreis) + h_cost;
    }

    // Wir berechnen 3 verschiedene Varianten für den Zeitraum und nehmen die billigste:
    // Option 1: Exakte Abrechnung (Stunden sind bereits gedeckelt)
    let option1 = getBestTimePrice(anzahlWochen, anzahlTage, stundenKosten);

    // Option 2: Wir machen aus den Stunden einfach einen vollen Tag 
    // (Wichtig, falls z.B. 2 Tage + 18h gebucht werden -> Wird dann als 1x 3-Tages-Paket berechnet)
    let option2 = getBestTimePrice(anzahlWochen, anzahlTage + 1, 0);

    // Option 3: Wir runden die verbleibenden Tage direkt zu einer vollen Woche auf
    // (Wichtig, da z.B. 6 volle Tage teurer sein können als 1 Woche)
    let option3 = getBestTimePrice(anzahlWochen + 1, 0, 0);

    // Nur der günstigste Zeitpreis von allen drei Optionen wird genommen
    let zeitPreis = Math.min(option1, option2, option3);

    // Membership-Rabatte auf Zeitpreis
    if (selectedMembersip === 'gold_membership' || selectedMembersip === 'black_membership') {
        zeitPreis *= 0.9;
    }

    gesamtPreis += zeitPreis;

    // 3. Kilometerpreis hinzufügen
    let kmPreis;
    const kmTarifUnter100 = tarif.kilometerTarife['unter100'][fahrzeugGroesse];
    const kmTarifUeber100 = tarif.kilometerTarife['ueber100'][fahrzeugGroesse];

    if (kilometer <= 100) {
        kmPreis = berechneKilometerPreis(kilometer, kmTarifUnter100);
    } else {
        kmPreis = berechneKilometerPreis(100, kmTarifUnter100) +
            berechneKilometerPreis(kilometer - 100, kmTarifUeber100);
    }

    // Membership-Rabatt auf Kilometer nur fuer Schwarz
    if (selectedMembersip === 'black_membership') {
        kmPreis *= 0.9;
    }

    // Kraftstoffzuschlag (wird nicht rabattiert)
    let kraftstoffZuschlagPreis = 0;
    if (kraftstoffzuschlag.value) {
        if (kraftstoffzuschlag.isPercent) {
            const kmGrundpreis = kilometer <= 100 ?
                berechneKilometerPreis(kilometer, kmTarifUnter100) :
                berechneKilometerPreis(100, kmTarifUnter100) + berechneKilometerPreis(kilometer - 100, kmTarifUeber100);
            kraftstoffZuschlagPreis = kmGrundpreis * kraftstoffzuschlag.value / 100;
        } else {
            kraftstoffZuschlagPreis = kilometer * kraftstoffzuschlag.value;
        }
        kmPreis = Math.max(0, kmPreis + kraftstoffZuschlagPreis);
    }

    gesamtPreis += kmPreis;

    let fahrtguthaben = 0;
    if (includeCredit) {
        if (selectedMembersip === 'gold_membership') {
            fahrtguthaben = 10;
        } else if (selectedMembersip === 'black_membership') {
            fahrtguthaben = 30;
        }
    }

    const gesamtNachGuthaben = Math.max(0, gesamtPreis - fahrtguthaben);

    return {
        zeitPreis,
        kilometerPreis: kmPreis,
        kraftstoffZuschlagPreis,
        fahrtguthaben,
        gesamtPreis: gesamtNachGuthaben,
        promoAktiv
    };
}

