    const timeParts = timeElement.textContent.split(':'); // Split auf hh:mm
    const hours = parseInt(timeParts[0], 10);
    const minutes = parseInt(timeParts[1], 10) || 0; // Falls nur Stunden angegeben

    // Erstelle ein neues Date-Objekt mit lokalem Datum und Uhrzeit
    return new Date(year, month, day, hours, minutes);
