function createARangePickerCalendar() {
    const monthYear = document.getElementById('month-year');
    const calendarDays = document.getElementById('calendar-days');
    const prevMonthBtn = document.getElementById('prev-month');
    const nextMonthBtn = document.getElementById('next-month');

    const startDateDisplay = document.getElementById('gf-start-date-display');
    const endDateDisplay = document.getElementById('gf-end-date-display');

    let currentYear = new Date().getFullYear();
    let currentMonth = new Date().getMonth();
    let calendarStartDate = null;
    let calendarEndDate = null;

    // Monat und Jahr aktualisieren
    function updateCalendar() {
        monthYear.textContent = `${new Date(currentYear, currentMonth).toLocaleString('de-DE', { month: 'long' })} ${currentYear}`;
        generateDays();
    }

    // Tage des Monats generieren
    function generateDays() {
        calendarDays.innerHTML = ''; // Reset Tage
        const today = new Date();
        today.setHours(0, 0, 0, 0); // Normalisiere auf Mitternacht

        const firstDayOfMonth = new Date(currentYear, currentMonth, 1);
        const lastDayOfMonth = new Date(currentYear, currentMonth + 1, 0);

        // Leerzellen für den Starttag hinzufügen
        for (let i = 0; i < firstDayOfMonth.getDay(); i++) {
            calendarDays.appendChild(document.createElement('span'));
        }

        for (let day = 1; day <= lastDayOfMonth.getDate(); day++) {
            const dayElement = document.createElement('span');
            const currentDate = new Date(currentYear, currentMonth, day);
            currentDate.setHours(0, 0, 0, 0); // Normalisiere auf Mitternacht

            dayElement.textContent = day;
            // Vermeide ISO-Parsing: speichere Timestamp
            dayElement.dataset.ts = String(currentDate.getTime());

            // Vergangene Tage ausgrauen und deaktivieren
            if (currentDate < today) {
                dayElement.classList.add('disabled');
            } else {
                dayElement.addEventListener('click', () => selectDate(currentDate));
                dayElement.addEventListener('mouseover', () => highlightRange(currentDate));
            }

            // Ausgewählte und Bereich hervorheben
            if (calendarStartDate && calendarEndDate && calendarStartDate.getTime() !== calendarEndDate.getTime()) {
                // Range-Auswahl
                if (currentDate.getTime() >= calendarStartDate.getTime() && currentDate.getTime() <= calendarEndDate.getTime()) {
                    if (currentDate.getTime() === calendarStartDate.getTime() || currentDate.getTime() === calendarEndDate.getTime()) {
                        dayElement.classList.add('selected');
                    } else {
                        dayElement.classList.add('in-range');
                    }
                }
            } else if (calendarStartDate && currentDate.getTime() === calendarStartDate.getTime()) {
                // Einzeltag-Auswahl
                dayElement.classList.add('selected');
            }

            calendarDays.appendChild(dayElement);
        }
    }

    // Event-Listener für mouseleave am Kalender hinzufügen
    const calendarContainer = document.querySelector('.gf-content-calendar');
    calendarContainer.addEventListener('mouseleave', () => {
        // Entferne alle Hover-Effekte wenn die Maus den Kalender verlässt
        const days = document.querySelectorAll('.days span[data-ts]');
        days.forEach(day => {
            day.classList.remove('hover-preview');
            // Behalte nur die echten in-range Klassen bei
            if (calendarStartDate && calendarEndDate && calendarStartDate.getTime() !== calendarEndDate.getTime()) {
                const ts = parseInt(day.dataset.ts, 10);
                if (ts > calendarStartDate.getTime() && ts < calendarEndDate.getTime()) {
                    day.classList.add('in-range');
                }
            }
        });
    });

    // Start- oder Enddatum setzen
    function selectDate(date) {
        // Vor dem Setzen: alle Hover-Previews entfernen, damit die Range sofort korrekt dargestellt wird
        document.querySelectorAll('.days span.hover-preview').forEach(el => el.classList.remove('hover-preview'));

        // Normalisiere das eingehende Datum auf Mitternacht
        const normalizedDate = new Date(date);
        normalizedDate.setHours(0, 0, 0, 0);

        if (!calendarStartDate || (calendarStartDate && calendarEndDate && calendarStartDate.getTime() !== calendarEndDate.getTime())) {
            // Kein Startdatum vorhanden oder Range bereits ausgewählt → neu starten
            calendarStartDate = normalizedDate;
            calendarEndDate = normalizedDate; // Gleiches Datum für eintägige Buchung
        } else if (calendarStartDate && calendarEndDate && calendarStartDate.getTime() === calendarEndDate.getTime()) {
            // Start = Ende (eintägige Buchung) → Ende setzen für Range
            if (normalizedDate.getTime() < calendarStartDate.getTime()) {
                calendarEndDate = calendarStartDate;
                calendarStartDate = normalizedDate;
            } else {
                calendarEndDate = normalizedDate;
            }
        }

        updateDateDisplays();
        updateCalendar();
        updatePrice();
    }

    // Hilfsfunktion zum Aktualisieren der Datumsanzeigen
    function updateDateDisplays() {
        if (!calendarStartDate) {
            startDateDisplay.textContent = '';
            endDateDisplay.textContent = '';
            return;
        }
        startDateDisplay.textContent = calendarStartDate.toLocaleDateString('de-DE');
        endDateDisplay.textContent = calendarEndDate ? calendarEndDate.toLocaleDateString('de-DE') : '';
    }

    // Bereich beim Hover hervorheben (optimiert)
    function highlightRange(hoverDate) {
        if (!calendarStartDate) return;

        // Normalisiere das Hover-Datum
        hoverDate.setHours(0, 0, 0, 0);
        const hoverTs = hoverDate.getTime();
        const startTs = calendarStartDate.getTime();
        const endTs = calendarEndDate ? calendarEndDate.getTime() : null;

        const days = document.querySelectorAll('.days span[data-ts]');
        days.forEach(day => {
            const ts = parseInt(day.dataset.ts, 10);
            day.classList.remove('in-range', 'hover-preview');

            // Wenn bereits eine Range ausgewählt ist (Start ≠ Ende)
            if (endTs && startTs !== endTs) {
                if (ts > startTs && ts < endTs) {
                    day.classList.add('in-range');
                }
            }
            // Wenn Start = Ende (eintägige Buchung) oder nur Start gesetzt
            else if (startTs && (startTs === endTs || !endTs)) {
                // Zeige Hover-Vorschau für potentielle Range (exklusiv beider Grenzen)
                if (ts !== startTs) {
                    if (ts > startTs && ts < hoverTs) {
                        day.classList.add('hover-preview');
                    } else if (ts < startTs && ts > hoverTs) {
                        day.classList.add('hover-preview');
                    }
                }
            }
        });
    }

    // Monat wechseln
    prevMonthBtn.addEventListener('click', () => {
        currentMonth--;
        if (currentMonth < 0) {
            currentMonth = 11;
            currentYear--;
        }
        updateCalendar();
    });

    nextMonthBtn.addEventListener('click', () => {
        currentMonth++;
        if (currentMonth > 11) {
            currentMonth = 0;
            currentYear++;
        }
        updateCalendar();
    });

    updateCalendar();

    // Keine initiale Markierung/Selektion setzen – erst auf Klick markieren
    // (Displays bleiben von setDefaultDates gesetzt)
}

function showOrHideCalendar() {
    const picker = document.querySelector('.gf-datetime-picker');
    const wasClosed = picker.classList.contains('closed');
    picker.classList.toggle('closed');

    // Beim Öffnen automatisch zu den Standard-/ausgewählten Zeiten scrollen
    if (wasClosed) {
        const startContainer = document.getElementById('start-time-scroll-container');
        const endContainer = document.getElementById('end-time-scroll-container');

        const scrollToSelected = (container, fallbackTime) => {
            if (!container) return;
            const target = container.querySelector('.time-scroll-item.selected') || container.querySelector(`[data-time="${fallbackTime}"]`);
            if (target) {
                const doScroll = () => {
                    try {
                        target.scrollIntoView({
                            block: 'center',
                            inline: 'nearest',
                            behavior: 'auto'
                        });
                    } catch (e) {
                        // Fallback: manuelles Zentrieren
                        const top = target.offsetTop - (container.clientHeight / 2) + (target.offsetHeight / 2);
                        container.scrollTop = Math.max(0, top);
                    }
                };
                // Warten bis das Layout nach dem Öffnen steht (Safari/WebKit Fix)
                setTimeout(() => requestAnimationFrame(doScroll), 0);
            }
        };

        scrollToSelected(startContainer, '07:00');
        scrollToSelected(endContainer, '14:00');
    }
}

function initTimeScrollContainer() {
    const startTimeDisplay = document.getElementById('gf-start-time-display');
    const endTimeDisplay = document.getElementById('gf-end-time-display');
    const startContainer = document.getElementById('start-time-scroll-container');
    const endContainer = document.getElementById('end-time-scroll-container');

    // Generiere alle Zeitslots von 00:00 bis 23:45 in 15-Minuten-Schritten
    const timeSlots = [];
    for (let hour = 0; hour < 24; hour++) {
        for (let minute = 0; minute < 60; minute += 15) {
            const timeString = `${hour.toString().padStart(2, '0')}:${minute.toString().padStart(2, '0')}`;
            timeSlots.push(timeString);
        }
    }

    // Erstelle HTML für beide Container
    function createTimeScrollItems(container, type) {
        container.innerHTML = '';

        timeSlots.forEach(time => {
            const timeItem = document.createElement('div');
            timeItem.className = 'time-scroll-item';
            timeItem.setAttribute('data-time', time);
            timeItem.textContent = time;

            timeItem.addEventListener('click', () => {
                // Entferne selected Klasse von allen Items in diesem Container
                container.querySelectorAll('.time-scroll-item').forEach(item => {
                    item.classList.remove('selected');
                });

                // Füge selected Klasse zum geklickten Item hinzu
                timeItem.classList.add('selected');

                // Aktualisiere die entsprechende Zeit-Anzeige
                if (type === 'start') {
                    startTimeDisplay.textContent = time;
                } else {
                    endTimeDisplay.textContent = time;
                }

                updatePrice();
            });

            container.appendChild(timeItem);
        });
    }

    // Erstelle beide Container
    createTimeScrollItems(startContainer, 'start');
    createTimeScrollItems(endContainer, 'end');

    // Setze Default-Zeiten (07:00 für Start, 14:00 für Ende) und markiere sie
    const startDefaultItem = startContainer.querySelector('[data-time="07:00"]');
    const endDefaultItem = endContainer.querySelector('[data-time="14:00"]');

    if (startDefaultItem) {
        startDefaultItem.classList.add('selected');
        startTimeDisplay.textContent = '07:00';
    }
    if (endDefaultItem) {
        endDefaultItem.classList.add('selected');
        endTimeDisplay.textContent = '14:00';
    }
}

